      var h = 1;
      for (final lines in wrapped) {
        if (lines.length > h) h = lines.length;
      }
      fragments.add(wrapped);
      heights.add(h);
    }

    for (var r = 0; r < rows.length; r++) {
      if (r == 1) {
        out.add(
          '$_dim${[for (var c = 0; c < widths.length; c++) '─' * (widths[c] + 2)].join('┼')}$_reset',
