  ) {
    final out = <String>[];

    // Per logical row: the wrapped fragments of every cell, and the tallest
    // cell's line count (the physical height of that logical row).
    final fragments = <List<List<String>>>[];
    final heights = <int>[];
    for (var r = 0; r < rows.length; r++) {
      if (r == 1) {
        fragments.add(const []);
        heights.add(1);
