      if (_hostExited) break;
      if (event is String) {
        await _submitLine(event);
        if (_hostExited) break;
        _render();
      } else if (event is KeyEvent) {
        _handleKey(event);
        if (_hostExited) break;
        _render();
      }
    }
  } finally {
    write('\x1b[?25h\x1b[?1049l');
  }
}

