    row.write(token);
    col += visibleLen;
    if (token.startsWith('\x1b')) {
      if (token == '\x1b[0m') {
        activeSgr.clear();
      } else {
        activeSgr.add(token);
      }
    }
  }

  void flushWord() {
    if (wordTokens.isEmpty) return;
    if (wordVisible > width) {
      // A single word longer than the width: hard-cut it across rows.
      if (col > 0) closeRow();
      for (final token in wordTokens) {
        final tokenWidth = _tokenWidth(token);
