void _handleDeleteKey(KeyEvent key) {
  switch (key.type) {
    case KeyType.backspace:
      _deleteLeft();
      _updateMenu();
      break;
    case KeyType.delete:
      _deleteRight();
      _updateMenu();
      break;
    default:
      break;
  }
}

