  KeyType.shiftTab,
  KeyType.up,
  KeyType.down,
  KeyType.pageUp,
  KeyType.pageDown,
  KeyType.unknown,
};

/// Keys that edit the input buffer (cursor motion and text edits).
static const _editKeys = {
  KeyType.left,
  KeyType.right,
  KeyType.home,
  KeyType.end,
  KeyType.backspace,
  KeyType.delete,
  KeyType.char,
};

/// Keys that only move the cursor within the input buffer.
static const _cursorKeys = {
  KeyType.left,
  KeyType.right,
  KeyType.home,
  KeyType.end,
};

void _handleKey(KeyEvent key) {
  // When the model picker is open, typing filters the list instead of
  // editing the input buffer.
  if (_menuOpen && _menuModelMode) {
    _handleModelMenuKey(key);
    return;
  }
  if (_menuScrollKeys.contains(key.type)) {
    _handleMenuScrollKey(key);
    return;
  }
  if (_editKeys.contains(key.type)) {
    _handleEditKey(key);
    return;
  }
  _handleMenuAcceptKey(key);
}

/// Enter/escape/tab: accept the open menu, close it, or submit the line.
void _handleMenuAcceptKey(KeyEvent key) {
  switch (key.type) {
    case KeyType.enter:
      if (_menuOpen) {
        _acceptMenuItem();
      } else {
        _submitCurrent();
      }
      break;
    case KeyType.escape:
      _closeMenu();
      break;
    case KeyType.tab:
      if (_menuOpen) _acceptMenuItem();
      break;
    default:
      break;
  }
}

/// Arrow/page keys: move the slash-menu selection when it is open.
void _handleMenuScrollKey(KeyEvent key) {
  if (key.type == KeyType.shiftTab || key.type == KeyType.up) {
    _scrollMenuUp();
    return;
  }
  if (key.type == KeyType.down) {
    _scrollMenuDown();
    return;
  }
  _handleMenuPageKey(key);
}

void _scrollMenuUp() {
  if (_menuOpen && _menuSelected > 0) _menuSelected--;
}

void _scrollMenuDown() {
  if (_menuOpen && _menuSelected < _menuItems.length - 1) {
    _menuSelected++;
  }
}

void _handleMenuPageKey(KeyEvent key) {
  switch (key.type) {
    case KeyType.pageUp:
      if (_menuOpen) _menuSelected = 0;
      break;
    case KeyType.pageDown:
      if (_menuOpen) _menuSelected = _menuItems.length - 1;
      break;
    default:
      break;
  }
}

/// Cursor motion and text editing of the input buffer.
void _handleEditKey(KeyEvent key) {
  if (_cursorKeys.contains(key.type)) {
    _handleCursorKey(key);
    return;
  }
  if (key.type == KeyType.char) {
    _handleCharKey(key);
    return;
  }
  _handleDeleteKey(key);
}

/// Cursor motion within the input buffer.
void _handleCursorKey(KeyEvent key) {
  switch (key.type) {
    case KeyType.left:
      if (_cursor > 0) _cursor--;
      break;
    case KeyType.right:
      if (_cursor < _text.length) _cursor++;
      break;
    case KeyType.home:
      _cursor = 0;
      break;
    case KeyType.end:
      _cursor = _text.length;
      break;
    default:
      break;
  }
}

/// Character insertion into the input buffer.
void _handleCharKey(KeyEvent key) {
  final ch = key.char;
  if (ch != null && ch.length == 1) {
    _insert(ch);
    _updateMenu();
  }
}

/// Backspace/delete: remove a character from the input buffer.
void _handleDeleteKey(KeyEvent key) {
  switch (key.type) {
    case KeyType.backspace:
      _deleteLeft();
      _updateMenu();
      break;
    case KeyType.delete:
      _deleteRight();
      _updateMenu();
      break;
    default:
      break;
  }
}

