        // Bold span straddling the wrap: the continuation must re-open bold
        // (dart_tui redraws rows independently — terminal state does not
        // carry across rows).
        final line = 'aa ${bold}bbbb bbbb$reset cc';
        final rows = wrapAnsiLine(line, 6);
