            tuiTextWidth(row),
            lessThanOrEqualTo(10),
            reason: 'row overflows: $row',
          );
        }
        // Reassembled visible text is unchanged except an edge-boundary
        // space, which stays dropped by design.
        expect(rows.join(), '${check * 5}tail');
      });

