/// Terminal width in columns.
final int columns;

/// Terminal height in rows.
final int rows;

/// Maximum number of menu items rendered at once; the rest scrolls.
static const _maxMenuItems = 10;

/// Maximum output history kept above the input line.
static const _maxOutputLines = 200;

final StringBuffer _buffer = StringBuffer();
var _cursor = 0;
var _menuOpen = false;
var _menuModelMode = false;
var _menuSelected = 0;
String _modelFilter = '';
List<MenuItem> _menuItems = const [];

/// Bounded output history shown above the input line.
final List<String> _outputLines = <String>[];

/// Previous rendered frame, padded to [rows] lines, used for diffing.
List<String> _previousLines = const [];

var _renderScheduled = false;

String get _text => _buffer.toString();

/// Appends host output (assistant text, tool notices, errors) above the
/// input line. Chunked streaming text is merged into the current last line;
/// embedded newlines split into new entries.
void appendOutput(String text, {bool newline = false}) {
  if (text.isEmpty && !newline) return;
  final parts = text.split('\n');
  if (_outputLines.isEmpty) _outputLines.add('');
  _outputLines[_outputLines.length - 1] += parts.first;
  for (var i = 1; i < parts.length; i++) {
    _outputLines.add(parts[i]);
  }
  if (newline) _outputLines.add('');
  if (_outputLines.length > _maxOutputLines) {
    _outputLines.removeRange(0, _outputLines.length - _maxOutputLines);
  }
  _scheduleRender();
}

void _scheduleRender() {
  if (_renderScheduled) return;
  _renderScheduled = true;
  scheduleMicrotask(() {
    _renderScheduled = false;
    _render();
  });
}

/// Runs the repl until the input key stream closes or the host marks exit.
Future<void> run(Stream<dynamic> keysOrLines) async {
  // Enter the alternate screen buffer and hide the hardware cursor so the
  // TUI frame never pollutes shell scrollback and redraws don't flicker.
  write('\x1b[?1049h\x1b[?25l');
  try {
    _render();
    await for (final event in keysOrLines) {
      if (_hostExited) break;
      if (event is String) {
        await _submitLine(event);
        if (_hostExited) break;
        _render();
      } else if (event is KeyEvent) {
        _handleKey(event);
        if (_hostExited) break;
        _render();
      }
    }
  } finally {
    write('\x1b[?25h\x1b[?1049l');
  }
}

bool get _hostExited => isExited?.call() ?? false;

/// Keys that move the slash-menu selection (or are ignored).
static const _menuScrollKeys = {
  KeyType.shiftTab,
  KeyType.up,
  KeyType.down,
  KeyType.pageUp,
  KeyType.pageDown,
  KeyType.unknown,
};

/// Keys that edit the input buffer (cursor motion and text edits).
static const _editKeys = {
  KeyType.left,
  KeyType.right,
  KeyType.home,
  KeyType.end,
  KeyType.backspace,
  KeyType.delete,
  KeyType.char,
};

/// Keys that only move the cursor within the input buffer.
static const _cursorKeys = {
  KeyType.left,
  KeyType.right,
  KeyType.home,
  KeyType.end,
};

void _handleKey(KeyEvent key) {
  // When the model picker is open, typing filters the list instead of
  // editing the input buffer.
  if (_menuOpen && _menuModelMode) {
    _handleModelMenuKey(key);
    return;
  }
  if (_menuScrollKeys.contains(key.type)) {
    _handleMenuScrollKey(key);
    return;
  }
  if (_editKeys.contains(key.type)) {
    _handleEditKey(key);
    return;
  }
  _handleMenuAcceptKey(key);
}

/// Enter/escape/tab: accept the open menu, close it, or submit the line.
void _handleMenuAcceptKey(KeyEvent key) {
  switch (key.type) {
    case KeyType.enter:
      if (_menuOpen) {
        _acceptMenuItem();
      } else {
        _submitCurrent();
      }
      break;
    case KeyType.escape:
      _closeMenu();
      break;
    case KeyType.tab:
      if (_menuOpen) _acceptMenuItem();
      break;
    default:
      break;
  }
}

/// Arrow/page keys: move the slash-menu selection when it is open.
void _handleMenuScrollKey(KeyEvent key) {
  if (key.type == KeyType.shiftTab || key.type == KeyType.up) {
    _scrollMenuUp();
    return;
  }
  if (key.type == KeyType.down) {
    _scrollMenuDown();
    return;
  }
  _handleMenuPageKey(key);
}

void _scrollMenuUp() {
  if (_menuOpen && _menuSelected > 0) _menuSelected--;
}

void _scrollMenuDown() {
  if (_menuOpen && _menuSelected < _menuItems.length - 1) {
    _menuSelected++;
  }
}

void _handleMenuPageKey(KeyEvent key) {
  switch (key.type) {
    case KeyType.pageUp:
      if (_menuOpen) _menuSelected = 0;
      break;
    case KeyType.pageDown:
      if (_menuOpen) _menuSelected = _menuItems.length - 1;
      break;
    default:
      break;
  }
}

/// Cursor motion and text editing of the input buffer.
void _handleEditKey(KeyEvent key) {
  if (_cursorKeys.contains(key.type)) {
    _handleCursorKey(key);
    return;
