/// Returns the raw sequence and its length.
_EscSeq _consumeEscape(String s, int start) {
  // Expect s[start] == '\x1b'
  if (start + 1 >= s.length) {
    return const _EscSeq(raw: '\x1b', length: 1);
  }

  final next = s[start + 1];
