        final seq = _consumeEscape(raw, i);
        state.accept(seq.raw);
        i += seq.length;
      } else {
        final nextEscape = raw.indexOf('\x1b', i);
        final plainEnd = nextEscape < 0 ? raw.length : nextEscape;
        final plainText = raw.substring(i, plainEnd);
