@override
void setUnicodeCore(bool enabled) {
  if (enabled == _unicodeCoreEnabled) return;
  _output.write(enabled ? '\x1b[?2027h' : '\x1b[?2027l');
  _unicodeCoreEnabled = enabled;
}

@override
void clearScreen() {
  _output.write('\x1b[H\x1b[2J');
