    if (tok.startsWith('\x1b[')) {
      final cm = RegExp(r'^\x1b\[(\d+);(\d+)H$').firstMatch(tok);
      if (cm != null) {
        row = int.parse(cm.group(1)!);
        col = int.parse(cm.group(2)!);
