final class ScheduledStatusMsg extends Msg {
  const ScheduledStatusMsg(this.count, this.nextDueMs);

  /// Deliverable pending records.
  final int count;

  /// Earliest due time (epoch ms); null when unknown.
  final int? nextDueMs;
}

