      model = send(model, OutputMsg('answer line $i', newline: true));
      renderer.render(model.view());
    }
    final out = buf.toString();

    expect(
      RegExp(r'\x1b\[[0-9]*S').hasMatch(out),
      isFalse,
      reason: 'row 0 stays pinned while streaming — a whole-screen scroll '

