      final dm = RegExp(r'^\x1b\[(\d*)T$').firstMatch(tok);
      if (dm != null) {
        out.write('«SCROLL DOWN ${dm.group(1)!.isEmpty ? 1 : dm.group(1)}»\n');
        continue;
