      } else if (t.startsWith('[') && RegExp(r'^\[\d*T').hasMatch(t)) {
        buf.write('<SD${t.substring(1, t.length - 1)}>');
      } else if (t.startsWith('[')) {
        buf.write('<${t.split('m').first}m>');
      } else {
        // text segment
        final text = t.replaceAll('\r', '<CR>').replaceAll('\n', '<LF>');
        if (curRow >= 14 && curRow <= 22) {
          buf.write('«R$curRow»$text');
        } else {
          buf.write('…');
        }
      }
    }
    print('=== TOKEN STREAM (rows 14-22) ===');
    print(buf.toString());
  });
}
