String _analyze(String raw) {
  final out = StringBuffer();
  // Tokenize: CSI sequences, OSC sequences, ESC single-char, text runs.
  final re = RegExp(
    r'\x1b\[[0-9;?]*[A-Za-z]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b.|[^\x1b]+',
  );
