  if (_hasRenderedFrame && view.content == _lastContent) {
    _cursorState.apply(_output, view.cursor);
    return;
  }
  final nextLines = view.content.split('\n');

  // gh-1197 AC3: a throw mid-frame must not leave the terminal inside
