    } else if (tok.startsWith('\x1b')) {
      // Other escapes: ignore.
    } else {
      final text = tok.replaceAll('\n', '<LF>');
      if (row == 17) {
        out.write('«R17: col $col: ${text.length} chars: "$text"»\n');
      }
      col += text.length;
    }
  }
  return out.toString();
}

