/// Runs [body] with print() redirected to [debugLogSink]...
Future<T> _silencePackagePrints<T>(Future<T> Function() body) {
  final sink = debugLogSink;
  if (sink == null) return body();
  return runZoned(body, zoneSpecification: ZoneSpecification(
    print: (self, parent, zone, line) => sink(line),
  ));
}
```

