      // it is dropped rather than becoming an invisible leading space.
      if (col + 1 <= width) {
        writeToken(token, 1);
      } else {
        closeRow();
      }
      continue;
    }
    wordTokens.add(token);
    if (!token.startsWith('\\x1b')) wordVisible += _tokenWidth(token);
