        isNotEmpty,
        reason: 'the package prints on the tag-generation path — the '
            'redirect must have something to catch',
      );
      expect(
        sinkLines.any((l) => l.contains('KBTagGeneratorAgent')),
        isTrue,
        reason: 'tag-generation prints must reach the sink',
      );
