  // that no longer fits hard-cuts across rows from here instead of pushing
  // the space onto its own blank row.
  var carriedBoundarySpace = false;

  void closeRow() {
    if (activeSgr.isNotEmpty) row.write('\x1b[0m');
    rows.add(row.toString());
    row
      ..clear()
      ..writeAll(activeSgr);
